import{_ as t}from"./chunks/calendar-month-1440.Ddt_hq6k.js";import{_ as n,c as a,o,ag as s}from"./chunks/framework.CazwtNDk.js";const i="/calendar/screenshots/calendar-week-1440.png",r="/calendar/screenshots/calendar-month-390.png",d="/calendar/screenshots/tools-export-desktop.png",y=JSON.parse('{"title":"User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"ui-guide.md","filePath":"ui-guide.md","lastUpdated":1788803607000}'),l={name:"ui-guide.md"};function c(h,e,g,p,u,m){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="user-guide" tabindex="-1">User Guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User Guide&quot;">​</a></h1><p>Open <code>/calendar/</code> on your running service, or follow the <a href="/calendar/quickstart">Quickstart</a> to start a local instance. Calendar combines an event editor, calendar views, entity assignments, and ICS tools in one interface.</p><h2 id="find-your-events" tabindex="-1">Find Your Events <a class="header-anchor" href="#find-your-events" aria-label="Permalink to &quot;Find Your Events&quot;">​</a></h2><p>Use <strong>Month</strong>, <strong>Week</strong>, <strong>Day</strong>, or <strong>Year</strong> to change the view. The navigation arrows move through the selected view; <strong>Today</strong> returns to the current date. Select a date in the calendar or mini-calendar to see its agenda.</p><p><img src="'+t+'" alt="Month view with calendar groups and the selected-day agenda"></p><p>Week and day views place timed events on a time grid, with all-day events above it. Select an event in the calendar or agenda to open its editor.</p><p><img src="'+i+'" alt="Week view showing timed events and an all-day row"></p><ul><li><strong>Search events</strong> matches event names, notes, and groups in the loaded calendar range.</li><li><strong>My calendars</strong> toggles group visibility without changing stored events.</li><li><strong>Show disabled events</strong> reveals disabled events in the UI; it does not enable them or include them in ICS exports.</li><li><strong>Entity</strong> requests events assigned to that entity from the server. Search and group visibility are local view controls, not additional access restrictions.</li><li><strong>Refresh calendar</strong> reloads data after changes made elsewhere.</li></ul><p>On mobile, use <strong>Toggle calendar filters</strong> to open navigation and filters. Month cells show event dots; tap a date to read its agenda and use the create button to add an event.</p><img src="'+r+'" width="390" alt="Mobile month view with event dots and a selected-day agenda"><h2 id="create-and-edit-events" tabindex="-1">Create and Edit Events <a class="header-anchor" href="#create-and-edit-events" aria-label="Permalink to &quot;Create and Edit Events&quot;">​</a></h2><ol><li>Choose <strong>New event</strong>, a date&#39;s add button, or a time slot in week/day view. On desktop, dragging across dates or time slots can prefill a range.</li><li>Enter an event name, choose an existing <strong>Calendar group</strong> or enter a new group name, and optionally add notes.</li><li>Choose all-day or timed scheduling, set the start and end, and confirm the <strong>Time zone</strong>.</li><li>Choose a <strong>Repeat</strong> preset if needed, then save. Use <strong>Additional settings</strong> for the disabled flag and optional <strong>Updated by</strong> audit label.</li></ol><p>To change an event, select it and save your changes. To remove it, choose delete in the editor and confirm. Disabling an event keeps it stored and editable while excluding it from ICS exports.</p><h3 id="dates-and-time-zones" tabindex="-1">Dates and Time Zones <a class="header-anchor" href="#dates-and-time-zones" aria-label="Permalink to &quot;Dates and Time Zones&quot;">​</a></h3><p>Timed events display in your browser&#39;s time zone; the editor uses the event&#39;s explicit time zone to interpret the entered date and time. All-day events retain their dates in the event&#39;s own zone instead of shifting with the browser zone.</p><p>The all-day editor&#39;s <strong>End date is inclusive</strong>: for a one-day event, use the same start and end date. The UI converts it to the following day&#39;s midnight for storage. The API and ICS use <strong>exclusive end timestamps</strong>. For example, an all-day event on September 7 ends at September 8, 00:00 in its event zone. A timed event ending at 10:00 does not occupy the next time slot beginning at 10:00.</p><h3 id="recurring-events" tabindex="-1">Recurring Events <a class="header-anchor" href="#recurring-events" aria-label="Permalink to &quot;Recurring Events&quot;">​</a></h3><p>Repeat options include daily, weekly, monthly, and yearly schedules, plus special holiday presets. Existing advanced RRULE/FUNC rules are retained when editing unless you replace the repeat selection. Occurrences are expanded by the server.</p><div class="warning custom-block"><p class="custom-block-title">Whole-Series Changes</p><p>Editing or deleting a recurring occurrence changes or deletes the entire stored series, not just that occurrence. There is no single-occurrence edit workflow.</p></div><h2 id="groups-and-entities" tabindex="-1">Groups and Entities <a class="header-anchor" href="#groups-and-entities" aria-label="Permalink to &quot;Groups and Entities&quot;">​</a></h2><p>A <strong>group</strong> is a label on an event, such as <code>Holidays</code> or <code>Team</code>. It organizes the calendar&#39;s colors and visibility. An <strong>entity</strong> is a named collection built from assignments to groups or individual events, such as an office or team calendar. Entities are not users, accounts, or permission boundaries.</p><p>In <strong>Calendar tools &gt; Assignments</strong>:</p><ol><li>Choose an entity or enter a new entity name.</li><li>Assign either a group or an individual event, then add the assignment.</li><li>Review the entity&#39;s assignments and remove individual assignments when no longer needed.</li></ol><p>A group assignment includes matching events, including events later added to that group. An individual-event assignment includes only that event. Entity names come from existing assignments; there is no separate entity registry. Removing an assignment does not delete its events. Older combined assignments are shown as group <strong>OR</strong> event; removing one removes that exact assignment.</p><p>Creating or importing events does not automatically assign them to the selected entity. If a new event is missing under an entity filter, assign its group or the event itself, or switch to all entities. The assignment picker includes disabled events and events outside the current calendar window. Large catalogs have a 20,000-row browser limit; use the API to manage datasets beyond that limit.</p><h2 id="import-download-and-subscribe" tabindex="-1">Import, Download, and Subscribe <a class="header-anchor" href="#import-download-and-subscribe" aria-label="Permalink to &quot;Import, Download, and Subscribe&quot;">​</a></h2><p>Open <strong>Calendar tools &gt; Import &amp; export</strong>.</p><p><img src="'+d+'" alt="Calendar tools showing download scope and subscription controls"></p><h3 id="import-an-ics-file" tabindex="-1">Import an ICS File <a class="header-anchor" href="#import-an-ics-file" aria-label="Permalink to &quot;Import an ICS File&quot;">​</a></h3><p>Choose an <code>.ics</code> file up to 9 MiB, optionally set an import group, time zone, and audit label, then choose <strong>Import file</strong>. Imports do not create entity assignments. Use the Assignments tab afterward if the imported events belong in an entity calendar.</p><h3 id="download-a-calendar" tabindex="-1">Download a Calendar <a class="header-anchor" href="#download-a-calendar" aria-label="Permalink to &quot;Download a Calendar&quot;">​</a></h3><p>Choose <strong>Export entity</strong> and <strong>Export group scope</strong>, then <strong>Download ICS</strong>. Only enabled events matching <strong>both</strong> scope controls are exported. Choosing all entities means all events, including events without assignments; choosing all groups applies no group restriction.</p><p>The export controls are independent of calendar search, hidden groups, and <strong>Show disabled events</strong>. Review the scope before sharing: a filtered screen is not a preview of the download&#39;s contents.</p><p>The optional <strong>Download year</strong> selects event series, not an exact clipping of the visible calendar range. Without a year, the default window is the previous year, current year, and next two years. An ICS download is a snapshot, not an automatically updating subscription.</p><h3 id="subscribe-from-another-calendar" tabindex="-1">Subscribe From Another Calendar <a class="header-anchor" href="#subscribe-from-another-calendar" aria-label="Permalink to &quot;Subscribe From Another Calendar&quot;">​</a></h3><p>Choose the export scope, then <strong>Copy subscription URL</strong> and add it as a calendar subscription in your calendar client. If clipboard access is unavailable, select and copy the displayed URL manually. Subscriptions use the same entity/group scope but never include the download year, retaining the rolling default window.</p><p>The URL must be reachable by the subscribing calendar provider. A localhost URL will not work for a remote provider. Refresh timing depends on that provider; updates may not appear immediately.</p><h2 id="deployment-security" tabindex="-1">Deployment Security <a class="header-anchor" href="#deployment-security" aria-label="Permalink to &quot;Deployment Security&quot;">​</a></h2><p>The UI and API provide <strong>no built-in authentication</strong>. Protect both at deployment with appropriate network restrictions or an authentication layer. The optional <code>Updated by</code> / audit label is sent as <code>X-User</code>; it is caller-supplied metadata, not a verified identity, login, or authorization check.</p><p>Entity filters and subscription URLs do not restrict access. A subscription URL is not an authorization token. When protecting the service, also plan how your calendar provider will reach and authenticate to the feed without exposing management endpoints or other calendars.</p>',40)]))}const w=n(l,[["render",c]]);export{y as __pageData,w as default};
